#include "../src/game/stage2_scene_events.hpp"
#include <cassert>
int main(int argc,char**argv){assert(argc==2);shin::AssetStore a(argv[1]);shin::IndexedSurface f(640,480);for(int type:{0x46,0x47,0x48,0x4a}){shin::PlayerPayload p;shin::initialize_player_payload(p,5,5);shin::Stage2SceneEvents e;int sounds=0;auto sound=[&](const char*){++sounds;};assert(e.start(type,p,0,sound));for(unsigned t=0;t<13000&&e.active();t+=16)e.tick(p,t,false,0,0,a,f,sound,[](auto&p){p.at(0x58)=0;});assert(!e.active()&&p.at(0x5c)==0&&sounds>=1);shin::initialize_player_payload(p,5,0);p.at(0x58)=-20;int x=p.at(8),collisions=0;assert(e.start(type,p,0,sound));for(unsigned t=0;t<3000&&e.active();t+=16){e.tick(p,t,false,0,std::max(0,p.at(12)-240),a,f,sound,[&](auto&body){++collisions;if(body.at(12)>=300){body.at(12)=300;body.at(0x58)=0;}});assert(p.at(8)==x&&p.at(12)<=300);}assert(collisions>0&&p.at(12)==300);if(e.active()){e.tick(p,3001,true,0,0,a,f,sound,{});e.tick(p,3002,false,0,0,a,f,sound,{});}assert(!e.active());assert(e.start(type,p,0,sound));e.tick(p,1,true,0,0,a,f,sound,{});assert(e.tick(p,2,false,0,0,a,f,sound,{}));}}
